import fs from 'fs-extra';
import path from 'path';
import glob from 'fast-glob';
import { pathToFileURL } from 'url';
import { LanderConfig, DomainRouteConfig } from '@/types/config';

export class WorkspaceGenerator {
  private config: LanderConfig;
  private workspaceDir: string;

  constructor(config: LanderConfig) {
    this.config = config;
    this.workspaceDir = path.resolve(config.projectRoot, 'node_modules/.lander-engine');
  }

  /**
   * Initializes the hidden workspace.
   */
  async generate() {
    await fs.ensureDir(this.workspaceDir);

    // 1. Copy/Link Astro Base Template
    const templateDir = path.resolve(this.config.engineRoot, 'templates/astro-base');

    if (await fs.pathExists(templateDir)) {
      // Clean target directory first to avoid stale files
      await fs.emptyDir(this.workspaceDir);
      
      try {
        await fs.copy(templateDir, this.workspaceDir, {
          overwrite: true,
          dereference: true,
        });

        // Resolve absolute paths for integrations to ensure Astro can find them even if not hoisted
        const compressorPath = this.resolvePackage('astro-compressor');

        const configPath = path.join(this.workspaceDir, 'astro.config.mjs');
        let configContent = await fs.readFile(configPath, 'utf8');
        configContent = configContent.replace('{{ASTRO_COMPRESSOR_PATH}}', compressorPath);
        
        await fs.writeFile(configPath, configContent);

      } catch (copyErr) {
        console.error('Failed to copy Astro template:', copyErr);
        throw new Error(`Failed to initialize workspace: ${copyErr instanceof Error ? copyErr.message : String(copyErr)}`);
      }
    } else {
      throw new Error(`Lander Engine template not found at ${templateDir}. This usually means the lander-engine package installation is incomplete or corrupted.`);
    }

    // 2. Copy User Assets Directory
    await this.copyAssets();

    // 3. Generate Registry Manifest
    await this.generateRegistryManifest();

    // 4. Generate domain routing entry point (if routing.config.js is present)
    await this.generateDomainRouting();

    // 4. Generate lander config json for global error pages
    await this.generateConfigJson();
  }

  /**
   * Copies the user's configured assets directory to the workspace.
   */
  private async copyAssets() {
    const assetsDir = path.resolve(this.config.projectRoot, this.config.assetsDir || 'assets');
    const targetSrcAssetsDir = path.join(this.workspaceDir, 'src/assets');
    const targetPublicAssetsDir = path.join(this.workspaceDir, 'public/assets');
    const targetPublicDir = path.join(this.workspaceDir, 'public');

    if (await fs.pathExists(assetsDir)) {
      try {
        await fs.copy(assetsDir, targetSrcAssetsDir, {
          overwrite: true,
          dereference: true,
        });
        await fs.copy(assetsDir, targetPublicAssetsDir, {
          overwrite: true,
          dereference: true,
        });
        await fs.copy(assetsDir, targetPublicDir, {
          overwrite: true,
          dereference: true,
        });
      } catch (copyErr) {
        console.error('Failed to copy assets directory:', copyErr);
      }
    } else {
      // Ensure target directories exist even if the user has no assets
      await fs.ensureDir(targetSrcAssetsDir);
      await fs.ensureDir(targetPublicAssetsDir);
      await fs.ensureDir(targetPublicDir);
    }
  }

  /**
   * Resolves a package path relative to the engine root as a file URL.
   */
  private resolvePackage(packageName: string): string {
    try {
      // Try to find it in the engine's node_modules
      const packagePath = path.join(this.config.engineRoot, 'node_modules', packageName);
      if (fs.existsSync(packagePath)) {
        return pathToFileURL(packagePath).toString();
      }
      // Fallback to plain name if not found (might be hoisted in user project)
      return packageName;
    } catch {
      return packageName;
    }
  }

  /**
   * Scans user directories and generates a manifest for the runtime registry.
   */
  private async generateRegistryManifest() {
    const componentsDir = path.resolve(this.config.projectRoot, this.config.componentsDir || 'components');
    const actionsDir = path.resolve(this.config.projectRoot, this.config.actionsDir || 'actions');

    const componentFiles = await glob('**/*.{tsx,jsx,astro,vue,svelte}', { cwd: componentsDir });
    const actionFiles = await glob('**/*.{ts,js}', { cwd: actionsDir });

    // 1. Generate core registry manifest (for actions and general registry)
    let manifestContent = `// Auto-generated manifest\n`;
    manifestContent += `import { registry } from 'lander-engine/core';\n\n`;

    // 2. Generate Registry.astro for static component mapping (Astro needs static imports for Islands)
    let astroRegistryContent = `---
// Auto-generated Astro Registry\n`;

    let componentIndex = 0;
    
    // Import all components
    componentFiles.forEach((file) => {
      const name = path.basename(file, path.extname(file));
      const importPath = path.resolve(componentsDir, file).replace(/\\/g, '/');
      astroRegistryContent += `import Component_${componentIndex} from '${importPath}';\n`;
      manifestContent += `import Component_${componentIndex} from '${importPath}';\n`;
      manifestContent += `registry.registerComponent('${name}', Component_${componentIndex});\n`;
      componentIndex++;
    });

    actionFiles.forEach((file, index) => {
      const name = path.basename(file, path.extname(file));
      const importPath = path.resolve(actionsDir, file).replace(/\\/g, '/');
      manifestContent += `import * as Action_${index} from '${importPath}';\n`;
      manifestContent += `registry.registerActions(Action_${index});\n`;
    });

    astroRegistryContent += `
const { component, props } = Astro.props;
---
`;

    componentIndex = 0;
    componentFiles.forEach((file) => {
      const name = path.basename(file, path.extname(file));
      const isAstroComponent = file.endsWith('.astro');
      
      if (isAstroComponent) {
        // Astro components don't need client: directive
        astroRegistryContent += `{component === '${name}' && <Component_${componentIndex} {...props} />}\n`;
      } else {
        // React/Vue/Svelte components get client:load
        astroRegistryContent += `{component === '${name}' && <Component_${componentIndex} {...props} client:load />}\n`;
      }
      componentIndex++;
    });

    const manifestPath = path.join(this.workspaceDir, 'src/registry-manifest.ts');
    const astroRegistryPath = path.join(this.workspaceDir, 'src/Registry.astro');
    
    await fs.ensureDir(path.dirname(manifestPath));
    await fs.writeFile(manifestPath, manifestContent);
    await fs.writeFile(astroRegistryPath, astroRegistryContent);
  }

  /**
   * Generates domain-to-campaign routing artifacts from routing.config.js.
   *
   * Produces three outputs:
   *  - src/pages/index.astro  — universal client-side domain redirect (works on any static host)
   *  - public/_redirects      — Netlify host-based redirect rules
   *  - public/vercel.json     — Vercel host-based redirect rules
   */
  private async generateDomainRouting() {
    const routingConfig = this.config.routingConfig;
    if (!routingConfig || Object.keys(routingConfig).length === 0) return;

    const jsonConfigsDir = path.resolve(
      this.config.projectRoot,
      this.config.jsonConfigsDir || 'json_configs'
    );

    // Normalize config and resolve domain → full path
    const domainPaths: Record<string, string> = {};
    const normalizedRouting: Record<string, DomainRouteConfig> = {};

    for (const [domain, routeConfig] of Object.entries(routingConfig)) {
      let campaignId: string;
      let renderFromRoot = false;
      let defaultStep: string | undefined;

      if (typeof routeConfig === 'string') {
        campaignId = routeConfig;
      } else {
        campaignId = routeConfig.campaign;
        renderFromRoot = routeConfig.renderFromRoot ?? false;
        defaultStep = routeConfig.defaultStep;
      }

      normalizedRouting[domain] = { campaign: campaignId, renderFromRoot, defaultStep };

      try {
        const flow = await fs.readJson(path.join(jsonConfigsDir, campaignId, 'flow.json'));
        const initialStep = defaultStep || flow.initialStep || 'main';

        let targetPath = `/${campaignId}/${initialStep}`;
        domainPaths[domain] = targetPath;
      } catch {
        console.warn(
          `routing.config.js: could not read flow.json for campaign "${campaignId}" (domain: ${domain}), falling back to /${campaignId}`
        );
        domainPaths[domain] = `/${campaignId}`;
      }
    }

    await fs.ensureDir(path.join(this.workspaceDir, 'src/pages'));
    await fs.ensureDir(path.join(this.workspaceDir, 'public'));
    await fs.ensureDir(path.join(this.workspaceDir, 'src'));

    // Write normalized routing config to be consumed by [...slug].astro and dispatcher
    await fs.writeJson(path.join(this.workspaceDir, 'src/domain-routing.json'), normalizedRouting, { spaces: 2 });

    // --- 1. src/pages/index.astro (universal — works on any static host) ---
    const domainMapJson = JSON.stringify(
      Object.entries(normalizedRouting).reduce((acc, [domain, cfg]) => {
        acc[domain] = {
          target: domainPaths[domain],
          renderFromRoot: cfg.renderFromRoot
        };
        return acc;
      }, {} as Record<string, { target: string; renderFromRoot?: boolean }>),
      null,
      2
    );
    const indexAstro = `---
// Auto-generated by lander-engine — domain routing entry point
// Redirects or rewrites each domain to its configured campaign's initial step.
---
<html>
  <head>
    <meta charset="utf-8" />
    <title>Redirecting...</title>
  </head>
  <body>
    <script>
      (function () {
        var domainMap = ${domainMapJson};
        var host = window.location.hostname;
        var config = domainMap[host];
        if (config) {
          if (config.renderFromRoot) {
            fetch(config.target + window.location.search)
              .then(function(res) { return res.text(); })
              .then(function(html) {
                document.open();
                document.write(html);
                document.close();
              })
              .catch(function() {
                window.location.replace(config.target + window.location.search);
              });
          } else {
            window.location.replace(config.target + window.location.search);
          }
        }
      })();
    </script>
    <noscript>Please enable JavaScript to use this site.</noscript>
  </body>
</html>
`;
    await fs.writeFile(path.join(this.workspaceDir, 'src/pages/index.astro'), indexAstro);

    // --- 2. public/_redirects (Netlify / Cloudflare Pages) ---
    let netlifyRedirects = `# Lander Engine — domain routing (auto-generated)\n`;
    for (const [domain, targetPath] of Object.entries(domainPaths)) {
      const cfg = normalizedRouting[domain];
      const status = cfg.renderFromRoot ? '200' : '302';
      netlifyRedirects += `/  ${targetPath}  ${status}!  Host=${domain}\n`;
    }

    // --- 3. public/vercel.json (Vercel) ---
    const vercelRedirects: any[] = [];
    const vercelRewrites: any[] = [];

    for (const [domain, targetPath] of Object.entries(domainPaths)) {
      const cfg = normalizedRouting[domain];
      if (cfg.renderFromRoot) {
        vercelRewrites.push({
          source: '/',
          destination: targetPath,
          has: [{ type: 'host', value: domain }],
        });
      } else {
        vercelRedirects.push({
          source: '/',
          destination: targetPath,
          has: [{ type: 'host', value: domain }],
          permanent: false,
        });
      }
    }
    const vercelJson = JSON.stringify({
      redirects: vercelRedirects.length > 0 ? vercelRedirects : undefined,
      rewrites: vercelRewrites.length > 0 ? vercelRewrites : undefined,
    }, null, 2);

    await fs.writeFile(path.join(this.workspaceDir, 'public/_redirects'), netlifyRedirects);
    await fs.writeFile(path.join(this.workspaceDir, 'public/vercel.json'), vercelJson);

    console.log(`Domain routing configured for ${Object.keys(domainPaths).length} domain(s).`);
  }

  private async generateConfigJson() {
    const configPath = path.join(this.workspaceDir, 'src/lander-config.json');
    const { errorPages, redirectPage } = this.config;
    await fs.ensureDir(path.dirname(configPath));
    await fs.writeJson(configPath, { errorPages: errorPages || {}, redirectPage: redirectPage || {} }, { spaces: 2 });
  }
}
